 function nativeContext(){return{key:token+':'+model?.phase+':'+(team==='solo'?activeSide():team),active:!!(fieldControls&&!disposed&&page==='play'&&runtime&&sceneView&&input&&!paused&&!model?.done&&!document.hidden&&document.hasFocus?.()!==false&&!document.querySelector?.('dialog[open]')),surface:$('.ww-play'),team,phase:model?.phase,camera:runtime?.camera,cameraLocked:deploymentMoves.size>0,side:owner=>team==='versus'?owner:team==='solo'?activeSide():0,validHandle:handle=>deploymentMoves.get(handle.id)===handle};}
 function previewDeployment(p,handle){if(paused||!handle||deploymentMoves.get(handle.id)!==handle||model.phase!=='build')return;if(team==='coop'&&(handle.owner===0?p.z>=-.1:p.z<.1))return;handle.preview={x:p.x,z:p.z};}
