 async function saveArmy(){if(!model)return;const side=activeSide(),rows=model.export(side);if(!rows.length){notify('Deploy an army first.');return;}const was=paused,serial=backgroundSerial,stamp=token;pause(true);const dialog=nameKeyboard(modal,{title:'Name your army',value:'Wobbly formation',onSave:async name=>{try{await mediaPut({id:uid(),name,type:'army',owner:ids[team==='versus'?side:0],at:Date.now(),favorite:false,data:{version:1,game:'wars',items:rows}});notify('Army saved. Existing formations are kept.');}catch{notify('Army could not be saved. Check device storage.');}}});dialog?.addEventListener('close',()=>{if(!disposed&&token===stamp)pause(was||serial!==backgroundSerial||document.hidden);},{once:true});}
